#include "../src/game/dlw_xui_document_backend.h"
#include <cassert>
#include <cstdio>
#include <cstring>
struct Host {int acquisitions=0,releases=0,rebuilds=0,native_entries=0,refuse_new=0,refuse_old=0,fail_acquire=0,compatible=1,scope=1,snapshot=1,fail_new=0,fail_old=0,fail_release=0; DlumaXuiDocumentBackend* backend=nullptr; bool reenter=false;};
static int Acquire(void* u,const char* p,DlumaXuiDocumentSource* s){auto& h=*static_cast<Host*>(u);if(++h.acquisitions==h.fail_acquire)return 0;s->handle=static_cast<uintptr_t>(h.acquisitions);s->bytes=100;std::strcpy(s->path,p);s->sha256[0]=static_cast<unsigned char>(s->handle);return 1;}
static int Compatible(void* u,const DlumaXuiDocumentSource*,const DlumaXuiDocumentSource*){return static_cast<Host*>(u)->compatible;}
static int Release(void* u,DlumaXuiDocumentSource* s){auto& h=*static_cast<Host*>(u);++h.releases;if(h.fail_release)return 0;std::memset(s,0,sizeof(*s));return 1;}
static int Current(void* u,const DlumaXuiDocumentIdentity*){return static_cast<Host*>(u)->scope;}
static int Snapshot(void* u,DlumaXuiDocumentSnapshot* s){auto& h=*static_cast<Host*>(u);s->component_classes[0]=10;return h.snapshot;}
static DlumaXuiDocumentRebuildResult Rebuild(void* u,const DlumaXuiDocumentIdentity*,const DlumaXuiDocumentSource* s,const DlumaXuiDocumentSnapshot* b){auto& h=*static_cast<Host*>(u);bool original=std::strcmp(s->path,"original.xui")==0;++h.rebuilds;assert(b->component_classes[0]==10);if(h.reenter)assert(dluma_xui_document_apply(h.backend)==DLUMA_XUI_DOCUMENT_BUSY);if(original?h.refuse_old:h.refuse_new)return DLUMA_XUI_DOCUMENT_REBUILD_REFUSED;++h.native_entries;return (original?!h.fail_old:!h.fail_new)?DLUMA_XUI_DOCUMENT_REBUILD_SUCCEEDED:DLUMA_XUI_DOCUMENT_REBUILD_ENTERED_FAILURE;}
static DlumaXuiDocumentIdentity Identity(){return {7,12,2,3};}
static void Init(DlumaXuiDocumentBackend& b,Host& h){DlumaXuiDocumentOps o={&h,Acquire,Compatible,Release,Current,Snapshot,Rebuild};h.backend=&b;dluma_xui_document_initialize(&b,&o);}
int main(){
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);h.refuse_new=1;assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_UNAVAILABLE);assert(h.rebuilds==1&&!h.native_entries&&h.releases==2&&b.original_valid&&b.state==DLUMA_XUI_DOCUMENT_FAILED);}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);h.snapshot=0;assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_UNAVAILABLE);assert(!h.rebuilds&&!h.native_entries&&h.releases==2&&b.original_valid);}
 {auto i=Identity();DlumaXuiDocumentBinding binding={0x1234,9,i};assert(dluma_xui_document_binding_matches(&binding,i,0x1234,9));assert(!dluma_xui_document_binding_matches(&binding,i,0x5678,9));assert(!dluma_xui_document_binding_matches(&binding,i,0x1234,10));++i.token;assert(!dluma_xui_document_binding_matches(&binding,i,0x1234,9));}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);assert(h.acquisitions==2&&h.rebuilds==0);h.reenter=true;assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_OK);assert(b.state==DLUMA_XUI_DOCUMENT_APPLIED&&h.rebuilds==1);auto wrong=Identity();++wrong.owner;assert(dluma_xui_document_restore(&b,wrong)==DLUMA_XUI_DOCUMENT_INVALID);assert(dluma_xui_document_restore(&b,Identity())==DLUMA_XUI_DOCUMENT_OK);assert(b.state==DLUMA_XUI_DOCUMENT_RESTORED&&h.rebuilds==2&&h.releases==2);assert(dluma_xui_document_restore(&b,Identity())==DLUMA_XUI_DOCUMENT_OK);}
 {DlumaXuiDocumentBackend b={};Host h;h.fail_acquire=2;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_SOURCE_FAILED);assert(h.rebuilds==0&&h.releases==1);}
 {DlumaXuiDocumentBackend b={};Host h;h.compatible=0;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_PREFLIGHT_FAILED);assert(h.rebuilds==0&&h.releases==2);}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);h.fail_new=1;assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_LOAD_FAILED);assert(h.rebuilds==2&&h.releases==2&&b.state==DLUMA_XUI_DOCUMENT_FAILED);}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);h.fail_new=h.fail_old=1;assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_ROLLBACK_FAILED);assert(h.releases==0&&b.state==DLUMA_XUI_DOCUMENT_RECOVERY_REQUIRED);h.fail_old=0;assert(dluma_xui_document_restore(&b,Identity())==DLUMA_XUI_DOCUMENT_OK);assert(h.rebuilds==3&&h.releases==2);}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);h.scope=0;assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_SCOPE_LOST);assert(h.rebuilds==0);assert(!dluma_xui_document_map_destroyed(&b,4));assert(dluma_xui_document_map_destroyed(&b,3));assert(h.releases==2);}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);assert(dluma_xui_document_cancel(&b,Identity())==DLUMA_XUI_DOCUMENT_OK);assert(h.rebuilds==0&&h.releases==2);}
 {DlumaXuiDocumentBackend b={};Host h;Init(b,h);assert(dluma_xui_document_prepare(&b,Identity(),"original.xui","replacement.xui")==DLUMA_XUI_DOCUMENT_OK);assert(dluma_xui_document_apply(&b)==DLUMA_XUI_DOCUMENT_OK);h.fail_release=1;assert(dluma_xui_document_restore(&b,Identity())==DLUMA_XUI_DOCUMENT_RELEASE_FAILED);assert(b.state==DLUMA_XUI_DOCUMENT_RELEASE_PENDING);int calls=h.rebuilds;h.fail_release=0;assert(dluma_xui_document_release(&b)==DLUMA_XUI_DOCUMENT_OK);assert(h.rebuilds==calls);}
 std::puts("XUI document backend passed");
}
